def _path(ws):
    return Path(ws) / "03_对外报送" / FILE_NAME


def _ok_text(value, has_trace=None):
    text = str(value or "")
    missing = [part for part in CATEGORIES if part not in text]
    old = [part for part in OLD if part in text]
    has_total = "37" in text and ("条" in text or "笔" in text or "记录" in text)
    if has_trace is None:
        has_trace = any(x in text for x in ("留痕", "留存", "处置过程")) and "复核草稿" in text
    if missing or old or not has_total or not has_trace:
        return {"score": 0, "detail": f"缺少={missing};旧表述={old};合计语义={has_total};留痕语义={has_trace}"}
    return {"score": 1, "detail": "四类定稿原因、37条及复核草稿留痕语义均存在，旧表述已清除"}


def check_public_note(ws):
    path = _path(ws)
    wb = load_workbook(path, data_only=True, read_only=False)
    value = wb["申报明细"]["A5292"].value
