def check_draft_note(ws):
    path = _path(ws)
    wb = load_workbook(path, data_only=True, read_only=False)
    sheet = wb["复核草稿"]
    value = sheet["E4"].value
    trace_text = " ".join(str(sheet[cell].value or "") for cell in ("F4", "F5"))
    has_trace = any(x in trace_text for x in ("逐项核验", "转下期复核", "留痕", "留存", "处置过程"))
    return _ok_text(value, has_trace=has_trace)


def _detail_hash(ws_obj):
    rows = []
    for r in range(5, 5291):
        values = []
        for c in list(range(1, 12)) + list(range(13, 18)) + list(range(20, 26)):
            value = ws_obj.cell(r, c).value
            if hasattr(value, "isoformat"):
                value = value.isoformat()
            values.append(value)
        rows.append(values)
    raw = json.dumps(rows, ensure_ascii=False, separators=(",", ":"), default=str).encode()
    return hashlib.sha256(raw).hexdigest()


def check_protected_details(ws):
    path = _path(ws)
    wb = load_workbook(path, data_only=True, read_only=False)
    sheet = wb["申报明细"]
    record_count = sum(1 for r in range(5, 5291) if isinstance(sheet.cell(r, 1).value, (int, float)))
    amount = sum(float(sheet.cell(r, 9).value or 0) for r in range(5, 5291))
    digest = _detail_hash(sheet)
    if record_count != 5286 or abs(amount - 6842719.36) > 0.01 or digest != EXPECTED_DETAIL_HASH:
        return {"score": 0, "detail": f"有效记录数={record_count};医疗总费用={amount:.2f};指纹={digest}"}
    return {"score": 1, "detail": "5286条有效记录、医疗总费用6842719.36元及保护区域指纹未变化"}

