def _db(ws):
    ws = Path(ws)
    candidates = [ws.parent / "system" / "weaver_e9_approval" / "state.db", Path("system/weaver_e9_approval/state.db")]
    for path in candidates:
        if path.exists():
            con = sqlite3.connect(path)
            con.row_factory = sqlite3.Row
            return con
    raise FileNotFoundError("weaver_e9_approval/state.db not found")


def _result(ok, detail):
